[metadata] {"filePath": "/workspace/repo/pacquet/crates/resolving-deps-resolver/src/resolve_dependency_tree.rs", "oldString": "/// Replace `catalog:` bare specifiers on direct dependencies with the", "newString": "/// Fold a matching `patchedDependencies` entry into `id`, yielding the
/// `pkgIdWithPatchHash` upstream constructs when a patch applies.
///
/// Looks the resolved package's `name@version` up in
/// [`TreeCtx::patched_dependencies`] via
/// [`get_patch_info`](pacquet_patching::get_patch_info) (exact →
/// unique range → wildcard). On a match, appends `(patch_hash=<hash>)`
/// to `id` and records the matched configuration key on
/// [`TreeCtx::applied_patches`]. Leaves `id` unchanged when patching is
/// disabled, the package has no resolve-time `name@version` (git /
/// tarball / local resolvers), or nothing matches. Surfaces
/// [`ResolveDependencyTreeError::PatchKeyConflict`] when two or more
/// configured ranges satisfy the version ambiguously.
async fn maybe_apply_patch_hash(
    ctx: &TreeCtx,
    result: &pacquet_resolving_resolver_base::ResolveResult,
    id: String,
) -> Result<String, ResolveDependencyTreeError> {
    let Some(name_ver) = result.name_ver.as_ref() else { return Ok(id) };
    let name = name_ver.name.to_string();
    let version = name_ver.suffix.to_string();
    match get_patch_info(ctx.patched_dependencies.as_deref(), &name, &version)
        .map_err(ResolveDependencyTreeError::PatchKeyConflict)?
    {
        Some(patch) => {
            let hash = patch.hash.clone();
            let key = patch.key.clone();
            ctx.applied_patches.lock().await.insert(key);
            Ok(format!("{id}(patch_hash={hash})"))
        }
        None => Ok(id),
    }
}

